const files = $input.first().json.files;

if (!files || files.length === 0) {
  return [{ json: { audioFiles: [], error: 'No files found' } }];
}

const audioFiles = files.filter(file => {
  const mimeType = file.mimetype || '';
  return mimeType.includes('audio') || 
         mimeType.includes('octet-stream') ||
         file.name?.toLowerCase().endsWith('.wav') ||
         file.name?.toLowerCase().endsWith('.mp3') ||
         file.name?.toLowerCase().endsWith('.m4a') ||
         file.name?.toLowerCase().endsWith('.ogg');
});

if (audioFiles.length > 0) {
  const file = audioFiles[0];
  const callid = `slack-${file.id}-${Date.now()}`;
  return [{
    json: {
      fileId: file.id,
      filename: file.name,
      urlPrivate: file.url_private,
      mimeType: file.mimetype,
      timestamp: file.created,
      user: file.user,
      callid: callid
    }
  }];
}

return [{ json: { audioFiles: [], error: 'No audio files found' } }];

let words = [];
let sttError = null;

const inputItem = $input.first();
if (inputItem.json.error) {
  sttError = inputItem.json.error.message || 'ElevenLabs STT unknown error';
  console.log('Error: ElevenLabs STT node error:', sttError);
} else {
  try {
    const elevenlabsOutput = inputItem.json;
    if (elevenlabsOutput && elevenlabsOutput.words && Array.isArray(elevenlabsOutput.words)) {
      words = elevenlabsOutput.words;
    } else {
      sttError = 'Transcription data (words array) not found or not an array';
      console.log('Warning:', sttError);
    }
  } catch (error) {
    sttError = 'ElevenLabs STT output could not be parsed: ' + error.message;
    console.log('Error:', sttError);
  }
}

let callid = 'unknown';
try {
  callid = $('Filter Audio Files').item.json.callid || 'unknown';
} catch (error) {
  console.log('Warning: callid could not be retrieved from Filter Audio Files:', error.message);
}

if (sttError) {
  return [
    {
      json: {
        callid: callid,
        conversation: [],
        error: sttError
      }
    }
  ];
}

const sortedWords = words.sort((a, b) => a.start - b.start);

const conversation = [];
let currentSpeaker = null;
let currentText = '';
let currentStart = null;
let currentEnd = null;
let conversationIndex = 0;

for (const word of sortedWords) {
  const speaker = word.speaker_id === undefined || word.speaker_id === null ? 'unknown' : `speaker_${word.speaker_id}`;
  const text = word.text || '';

  if (speaker !== currentSpeaker) {
    if (currentSpeaker !== null && currentText.trim() !== '') {
      conversation.push({
        speaker: currentSpeaker,
        text: currentText.trim(),
        start: currentStart,
        end: currentEnd,
        conversation_index: conversationIndex++
      });
    }
    currentSpeaker = speaker;
    currentText = text;
    currentStart = word.start;
    currentEnd = word.end;
  } else {
    currentText += ' ' + text;
    currentEnd = word.end;
  }
}

if (currentText.trim() !== '') {
  conversation.push({
    speaker: currentSpeaker,
    text: currentText.trim(),
    start: currentStart,
    end: currentEnd,
    conversation_index: conversationIndex++
  });
}

return [
  {
    json: {
      callid: callid,
      conversation: conversation,
      wordCount: words.length,
      speakerCount: [...new Set(words.map(w => `speaker_${w.speaker_id}`))].length
    }
  }
];

let conversation;
let callid_from_input = 'unknown';
try {
  const convNodeOutput = $input.first().json;
  conversation = convNodeOutput.conversation || [];
  callid_from_input = convNodeOutput.callid || 'unknown';
  if (!Array.isArray(conversation)) {
    console.log('Warning: conversation is not an array');
    conversation = [];
  }
} catch (error) {
  console.log('Error (Create Analysis Prompt - conversation):', error.message);
  conversation = [];
}

const promptsystem = `You are a call center conversation analyzer.

Below is a JSON array called conversation, where each item represents a speech block with the following structure:
{
  "speaker": "speaker_0" or "speaker_1" or "unknown",
  "text": "spoken words",
  "start": float (start time in seconds),
  "end": float (end time in seconds),
  "conversation_index": integer (order of conversation)
}

Your task is to analyze this conversation based on the following criteria. Respond with true, false, or "unknown" for boolean questions. For the sale value scale, use an integer from 1 to 5 if a sale occurred, otherwise use 0 or null.

Instructions:
1. Determine which speaker is the call center agent and which is the customer.
2. Analyze the customer's emotional tone (e.g., calm, angry, excited, confused, etc.).
3. Assess overall conversation sentiment (positive, negative, neutral).
4. Identify the main topic (e.g., complaint, sales, technical issue, billing).
5. Extract the most significant term/keyword (e.g., 'approved', 'canceled', 'offer', 'refund').
6. Classify the general experience (acceptable, unacceptable, neutral).
7. Summarize the customer's experience in one word (e.g., frustrating, smooth, excellent).
8. Was an email address asked for or provided?
9. Did any positive comments from the customer pass the sale?
10. Did any negative comments from the customer pass the sale?
11. Was the price negotiated?
12. Was the customer addressed politely?
13. Was the conversation fun (humor, pleasant exchange)?
14. Were service advantages mentioned?
15. Were other platforms mentioned?
16. What was the sale outcome?
17. Sale value scale (1-5 if sale occurred, 0 or null otherwise).
18. Did the agent ask if commenters were known?
19. Were high profile advantages mentioned?

Respond with valid JSON only. Use this exact schema:
{
  "sentiment": "positive/negative/neutral",
  "topic": "main topic",
  "significant_term": "key term",
  "general_value": "acceptable/unacceptable/neutral",
  "general_experience": "one word",
  "email_inquired": true/false/unknown,
  "positive_comment_passed_sale": true/false/unknown,
  "negative_comment_passed_sale": true/false/unknown,
  "price_negotiated": true/false/unknown,
  "customer_addressed_politely": true/false/unknown,
  "conversation_fun": true/false/unknown,
  "service_advantages_mentioned": true/false/unknown,
  "other_platforms_mentioned": true/false/unknown,
  "sale_outcome": "sold/not sold/unknown",
  "sale_value_scale": 0-5 or null,
  "asked_if_commenters_known": true/false/unknown,
  "high_profile_advantages_mentioned": true/false/unknown
}
`;

const formattedConversation = conversation.map(conv => 
  `[${conv.speaker}]: ${conv.text}`
).join('\n');

return [{
  json: {
    callid: callid_from_input,
    promptsys: promptsystem,
    promtuser: `Analyze this call conversation:\n\n${formattedConversation}\n\nProvide the analysis in valid JSON format matching the schema above.`
  }
}];

const llmInputItem = $input.first();
let output = {};
let llmError = null;

const normalizeValue = (val) => {
  return (val === 'unknown' || val === undefined) ? null : val;
};

const defaultFields = {
  sentiment: null,
  topic: null,
  significant_term: null,
  general_value: null,
  general_experience: null,
  email_inquired: null,
  positive_comment_passed_sale: null,
  negative_comment_passed_sale: null,
  price_negotiated: null,
  customer_addressed_politely: null,
  conversation_fun: null,
  service_advantages_mentioned: null,
  other_platforms_mentioned: null,
  sale_outcome: null,
  sale_value_scale: null,
  asked_if_commenters_known: null,
  high_profile_advantages_mentioned: null,
  llm_error_message: null
};

let callid = 'unknown';
try {
  callid = $('Process Conversation').item.json.callid || 'unknown';
} catch (error) {
  console.log('CallID not found:', error.message);
}

if (llmInputItem.json.error) {
  llmError = llmInputItem.json.error.message || 'LLM chain unknown error';
  console.log('LLM Error:', llmError);
  output = {
    ...defaultFields,
    llm_error_message: llmError
  };
} else if (llmInputItem.json && llmInputItem.json.text) {
  let responseText = llmInputItem.json.text;

  if (responseText.startsWith('```json')) {
    responseText = responseText.slice(7).trim();
    if (responseText.endsWith('```')) {
      responseText = responseText.slice(0, -3).trim();
    }
  } else if (responseText.startsWith('```')) {
    responseText = responseText.slice(3).trim();
    if (responseText.endsWith('```')) {
      responseText = responseText.slice(0, -3).trim();
    }
  }

  try {
    const parsed = JSON.parse(responseText);
    output = {
      sentiment: normalizeValue(parsed.sentiment) || defaultFields.sentiment,
      topic: normalizeValue(parsed.topic) || defaultFields.topic,
      significant_term: normalizeValue(parsed.significant_term) || defaultFields.significant_term,
      general_value: normalizeValue(parsed.general_value) || defaultFields.general_value,
      general_experience: normalizeValue(parsed.general_experience) || defaultFields.general_experience,
      email_inquired: normalizeValue(parsed.email_inquired) || defaultFields.email_inquired,
      positive_comment_passed_sale: normalizeValue(parsed.positive_comment_passed_sale) || defaultFields.positive_comment_passed_sale,
      negative_comment_passed_sale: normalizeValue(parsed.negative_comment_passed_sale) || defaultFields.negative_comment_passed_sale,
      price_negotiated: normalizeValue(parsed.price_negotiated) || defaultFields.price_negotiated,
      customer_addressed_politely: normalizeValue(parsed.customer_addressed_politely) || defaultFields.customer_addressed_politely,
      conversation_fun: normalizeValue(parsed.conversation_fun) || defaultFields.conversation_fun,
      service_advantages_mentioned: normalizeValue(parsed.service_advantages_mentioned) || defaultFields.service_advantages_mentioned,
      other_platforms_mentioned: normalizeValue(parsed.other_platforms_mentioned) || defaultFields.other_platforms_mentioned,
      sale_outcome: normalizeValue(parsed.sale_outcome) || defaultFields.sale_outcome,
      sale_value_scale: parsed.sale_value_scale !== undefined && parsed.sale_value_scale !== null ? parseInt(parsed.sale_value_scale) : defaultFields.sale_value_scale,
      asked_if_commenters_known: normalizeValue(parsed.asked_if_commenters_known) || defaultFields.asked_if_commenters_known,
      high_profile_advantages_mentioned: normalizeValue(parsed.high_profile_advantages_mentioned) || defaultFields.high_profile_advantages_mentioned
    };
  } catch (parseError) {
    console.log('JSON parse error:', parseError.message);
    llmError = 'Failed to parse LLM JSON response: ' + parseError.message;
    output = {
      ...defaultFields,
      llm_error_message: llmError
    };
  }
}

return [{
  json: {
    callid: callid,
    ...output
  }
}];

const item = $input.first().json;
const output = $input.first().json;

const sentimentEmoji = {
  'positive': '😊',
  'negative': '😞',
  'neutral': '😐'
};

const saleOutcomeEmoji = {
  'sold': '✅',
  'not sold': '❌',
  'unknown': '❓'
};

const formatBoolean = (val) => {
  if (val === true) return '✓';
  if (val === false) return '✗';
  return '❓';
};

return [{
  json: {
    callid: item.callid,
    sentiment_emoji: sentimentEmoji[output.sentiment?.toLowerCase()] || '',
    sale_outcome_emoji: saleOutcomeEmoji[output.sale_outcome?.toLowerCase()] || '',
    email_inquired: formatBoolean(output.email_inquired),
    price_negotiated: formatBoolean(output.price_negotiated),
    customer_addressed_politely: formatBoolean(output.customer_addressed_politely),
    conversation_fun: formatBoolean(output.conversation_fun),
    service_advantages_mentioned: formatBoolean(output.service_advantages_mentioned),
    positive_comment_passed_sale: formatBoolean(output.positive_comment_passed_sale),
    negative_comment_passed_sale: formatBoolean(output.negative_comment_passed_sale),
    ...output
  }
}];

